css:
.hero__title {
  position: fixed;
  top: calc(50% - 56px - clamp(82px, 8vw, 126px));
  left: 4%;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  margin: 0;
  width: 96vw;
  color: #ffffff;
  font-weight: 200;
  letter-spacing: 0;
  line-height: 0.88;
  pointer-events: none;
  transform: translate3d(0, var(--scroll-y, 0px), 0);
  will-change: transform, opacity;
}
